    string[] lines = input.Split(new[] { "\r\n" }, StringSplitOptions.None);

    foreach (string line in lines)
    {
        string[] parts = line.Split(':');
        fromList.Add(parts[0]);
        toList.Add(parts[1].Trim().Split(' '));
    }

    long pathCount = CountPaths("svr", false, false);

    Console.WriteLine(pathCount);

    long CountPaths(string current, bool fft, bool dac)
    {
        if (current == "fft") fft = true;
        if (current == "dac") dac = true;

        string key = current + "|" + fft + "|" + dac;

        if (memo.ContainsKey(key))
            return memo[key];

        if (current == "out")
        {
            long result = (fft && dac) ? 1 : 0;
            memo[key] = result;
            return result;
        }

        int index = -1;
        for (int i = 0; i < fromList.Count; i++)
        {
            if (fromList[i] == current)
            {
                index = i;
                break;
            }
        }

        if (index == -1)
            return 0;

        long total = 0;

        foreach (string next in toList[index])
        {
            total += CountPaths(next, fft, dac);
        }

        memo[key] = total;
        return total;
    }
